<script setup lang="ts">import {computed,shallowRef} from "vue";import {ChevronDown,ChevronUp} from "lucide-vue-next";import type{CatalogoAceiteRelacionado}from "@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.types";const props=defineProps<{items:readonly CatalogoAceiteRelacionado[]}>();const expanded=shallowRef(false);const ordered=computed(()=>[...props.items].sort((a,b)=>a.nombre.localeCompare(b.nombre,"es",{sensitivity:"base"})));const visible=computed(()=>expanded.value?ordered.value:ordered.value.slice(0,4));const remaining=computed(()=>Math.max(ordered.value.length-4,0));</script>
<template><section aria-labelledby="related-oils-title"><h3 id="related-oils-title" class="text-xs font-semibold text-gray-800">Aceites relacionados <span class="ml-1 tabular-nums text-gray-500">{{ items.length }}</span></h3><p v-if="!items.length" class="mt-2 text-xs text-gray-500">Sin aceites relacionados</p><div v-else class="mt-2 flex flex-wrap gap-1.5"><span v-for="item in visible" :key="item.id" class="inline-flex items-center gap-2 rounded-md bg-main/6 px-2 py-1.5 text-xs text-main">{{ item.nombre }}<strong class="tabular-nums">{{ new Intl.NumberFormat('es').format(item.cantidadEquipos) }}</strong></span><button v-if="remaining||expanded" type="button" class="inline-flex min-h-8 cursor-pointer items-center gap-1 rounded-md border border-main/15 px-2 text-xs font-semibold text-main" :aria-expanded="expanded" @click="expanded=!expanded">{{ expanded?'Ver menos':`+${remaining}` }}<component :is="expanded?ChevronUp:ChevronDown" class="h-3.5 w-3.5"/></button></div></section></template>
